CREATE TABLE IF NOT EXISTS members (id INTEGER PRIMARY KEY REFERENCES roster(id), role TEXT NOT NULL DEFAULT 'member', invited INTEGER NOT NULL DEFAULT 0, suspended INTEGER NOT NULL DEFAULT 0, attendance_private INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS login_links (token TEXT PRIMARY KEY, member INTEGER NOT NULL, expires INTEGER NOT NULL, destination TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, member INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, hits INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profile_fields (member INTEGER NOT NULL, field TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(member,field));
CREATE TABLE IF NOT EXISTS yearbook_public (member INTEGER PRIMARY KEY, fields TEXT NOT NULL, images TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, title TEXT NOT NULL COLLATE NOCASE UNIQUE, kind TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, redirect TEXT);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, author INTEGER NOT NULL, subject INTEGER, topic TEXT, body TEXT NOT NULL, created INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, origin TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS posts_order ON posts(hidden,created DESC,id DESC);
CREATE TABLE IF NOT EXISTS uploads (id TEXT PRIMARY KEY, owner INTEGER NOT NULL, object_key TEXT NOT NULL, type TEXT NOT NULL, digest TEXT NOT NULL, caption TEXT NOT NULL, post TEXT, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, post TEXT NOT NULL, author INTEGER NOT NULL, body TEXT NOT NULL, created INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS likes (post TEXT NOT NULL, member INTEGER NOT NULL, PRIMARY KEY(post,member));
CREATE TABLE IF NOT EXISTS tags (post TEXT NOT NULL, member INTEGER NOT NULL, status TEXT NOT NULL, PRIMARY KEY(post,member));
CREATE TABLE IF NOT EXISTS muted_subjects (post TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS attendance (member INTEGER PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('attending','declined','unknown')));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter INTEGER NOT NULL, target_type TEXT NOT NULL, target TEXT NOT NULL, reason TEXT NOT NULL, created INTEGER NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, actor INTEGER NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, reason TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_reads (member INTEGER PRIMARY KEY, seen INTEGER NOT NULL);
